export const RESPONSIBILITIES = Object.freeze([
  'direct-business-proof',
  'fixture-construction',
  'process-contract',
  'git-process-integration',
  'cross-language-packaging',
  'large-state-artifact-boundary',
  'concurrency-timing',
  'unknown',
]);

